Singularity.PlanarRuns.KeepsRho.one_le.type:
∀ {σ : Type u_1} [inst : Fintype σ] {θ : ℝ} {k : Type u_2} [inst_1 : Field k] {p : ℕ} {w : ℕ → Bool} {t : ℕ → σ → k}
  {g : MvPolynomial σ (HahnSeries (Singularity.PlanarRuns.CornerExp θ) k)} {ρ₀ : ℕ∞},
  Singularity.PlanarRuns.KeepsRho p w t g ρ₀ → 1 ≤ ρ₀

Singularity.PlanarRuns.classPart_of_inCl.type:
∀ {θ : ℝ} (p : ℕ) {k : Type u_1} [inst : Field k] {c : ZMod p × ZMod p}
  {x : HahnSeries (Singularity.PlanarRuns.CornerExp θ) k},
  Singularity.PlanarRuns.InClass p c x → Singularity.PlanarRuns.classPart p c x = x

Singularity.PlanarRuns.coeff_eq_zero_of_.type:
∀ {θ : ℝ} {k : Type u_1} [inst : Field k] {x : HahnSeries (Singularity.PlanarRuns.CornerExp θ) k}
  {r : Singularity.PlanarRuns.CornerExp θ},
  (∀ s ∈ x.support, Singularity.PlanarRuns.CornerExp.val θ r < Singularity.PlanarRuns.CornerExp.val θ s) → x.coeff r = 0

Singularity.PlanarRuns.coeff_hasse_eq_ze.type:
∀ {σ : Type u_1} {R : Type u_2} [inst : Fintype σ] [DecidableEq σ] [inst_2 : CommSemiring R] {k m : σ →₀ ℕ}
  {f : MvPolynomial σ R},
  f.totalDegree < Finsupp.degree m + Finsupp.degree k → (Singularity.PlanarRuns.hasse k f).coeff m = 0

Singularity.PlanarRuns.hahnVal_le_of_mem.type:
∀ {θ : ℝ} {k : Type u_1} [inst : Field k] {x : HahnSeries (Singularity.PlanarRuns.CornerExp θ) k}
  {r : Singularity.PlanarRuns.CornerExp θ},
  r ∈ x.support → (Singularity.PlanarRuns.hahnVal θ k) x ≤ ↑(Singularity.PlanarRuns.CornerExp.val θ r)

Singularity.PlanarRuns.hasse_eq_C_of_tot.type:
∀ {σ : Type u_1} {K : Type u_2} [inst : Fintype σ] [DecidableEq σ] [inst_2 : Field K] {g : MvPolynomial σ K}
  {k : σ →₀ ℕ},
  Singularity.PlanarRuns.ord k = g.totalDegree → Singularity.PlanarRuns.hasse k g = MvPolynomial.C (g.coeff k)

Singularity.PlanarRuns.mem_powerForm.type:
∀ {σ : Type u_1} {K : Type u_2} [inst : DecidableEq σ] [inst_1 : Field K] {p : ℕ} {K0 : Subring K}
  {h : MvPolynomial σ K},
  h ∈ Singularity.PlanarRuns.powerForm p K0 ↔ ∀ (k : σ →₀ ℕ), h.coeff k ≠ 0 → (∀ (i : σ), p ∣ k i) ∧ h.coeff k ∈ K0

Singularity.PlanarRuns.ordAt_le_termOrd.type:
∀ {σ : Type u_1} [inst : Fintype σ] {θ : ℝ} {k : Type u_2} [inst_1 : Field k] {w : ℕ → Bool} {m : ℕ}
  {h : MvPolynomial σ (HahnSeries (Singularity.PlanarRuns.CornerExp θ) k)} {q : σ →₀ ℕ}
  {r : Singularity.PlanarRuns.CornerExp θ},
  (h.coeff q).coeff r ≠ 0 → Singularity.PlanarRuns.ordAt w m h ≤ ↑(Singularity.PlanarRuns.termOrd w m q r)

Singularity.PlanarRuns.val_order_le.type:
∀ {θ : ℝ} {k : Type u_1} [inst : Field k] {x : HahnSeries (Singularity.PlanarRuns.CornerExp θ) k}
  {r : Singularity.PlanarRuns.CornerExp θ},
  r ∈ x.support → Singularity.PlanarRuns.CornerExp.val θ x.order ≤ Singularity.PlanarRuns.CornerExp.val θ r

Singularity.PurelyInseparableEquation.or.type:
∀ {σ : Type u_1} {R : Type u_2} [inst : CommRing R] (p : ℕ) [Fact (Nat.Prime p)] [CharP R p] (a : σ → R) {z : σ}
  {G : MvPolynomial σ R},
  z ∉ G.vars → Singularity.ord ((Singularity.PurelyInseparableEquation.shift a) (MvPolynomial.X z ^ p + G)) ≤ ↑p

Singularity.X_mul_pderiv_C_mul_X_mem.type:
∀ {σ : Type u_1} {k : Type u_2} [inst : Field k] [DecidableEq σ] (c : k) (i l : σ),
  MvPolynomial.X i * (MvPolynomial.pderiv i) (MvPolynomial.C c * MvPolynomial.X l) ∈
