Singularity.algebraicIndependent_of_resi.type:
∀ {k : Type u_1} {K : Type u_2} [inst : Field k] [inst_1 : Field K] [inst_2 : Algebra k K] {V : ValuationSubring K}
  [inst_3 : Algebra k ↥V] [IsScalarTower k (↥V) K] {κ : Type u_3} {y : κ → ↥V},
  (AlgebraicIndependent k fun i => (IsLocalRing.residue ↥V) (y i)) → AlgebraicIndependent k fun i => ↑(y i)

Singularity.cast_mul_mem_weightSpace.type:
∀ {k : Type u_1} {R : Type u_2} [inst : CommRing k] [inst_1 : CommRing R] [inst_2 : Algebra k R] {p : ℕ}
  [Fact (Nat.Prime p)] (δ : Derivation k R R) {j : ZMod p} {g : R},
  g ∈ Singularity.weightSpace δ j → ∀ (z : ZMod p), z.cast * g ∈ Singularity.weightSpace δ j

Singularity.centerChartTransformIdeal_sp.type:
∀ {σ : Type u_1} {R : Type u_2} [inst : CommRing R] [inst_1 : DecidableEq σ] [IsDomain R] {S : Finset σ} {c : σ} {m : ℕ}
  {T : Set (MvPolynomial σ R)},
  Ideal.span T ≤ Singularity.chartCenterIdeal S ^ m →
    Singularity.centerChartTransformIdeal S c m (Ideal.span T) =
      Ideal.span {g | ∃ f ∈ T, (Singularity.chartSubst S c) f = MvPolynomial.X c ^ m * g}

∀ {σ : Type u_1} {R : Type u_2} [inst : CommRing R] [IsDomain R] [inst_2 : DecidableEq σ] {S : Finset σ} {c l : σ},
  l ∈ S →
    l ≠ c → Singularity.centerChartTransformIdeal S c 1 (Ideal.span {MvPolynomial.X l}) = Ideal.span {MvPolynomial.X l}

∀ {σ : Type u_1} {R : Type u_2} [inst : CommRing R] [IsDomain R] [inst_2 : DecidableEq σ] {S : Finset σ} (c : σ)
  {l : σ},
  l ∉ S → Singularity.centerChartTransformIdeal S c 0 (Ideal.span {MvPolynomial.X l}) = Ideal.span {MvPolynomial.X l}

Singularity.coe_aeval.type:
∀ {k : Type u_1} {K : Type u_2} [inst : Field k] [inst_1 : Field K] [inst_2 : Algebra k K] {V : ValuationSubring K}
  [inst_3 : Algebra k ↥V] [IsScalarTower k (↥V) K] {κ : Type u_3} (y : κ → ↥V) (p : MvPolynomial κ k),
  ↑((MvPolynomial.aeval y) p) = (MvPolynomial.aeval fun i => ↑(y i)) p

Singularity.commute_castHom_moduleEnd.type:
∀ {k : Type u_1} {R : Type u_2} [inst : CommRing k] [inst_1 : CommRing R] [inst_2 : Algebra k R] {p : ℕ}
  [Fact (Nat.Prime p)] [inst_4 : CharP R p] (i : ZMod p) (f : Module.End k R),
  Commute ((ZMod.castHom ⋯ (Module.End k R)) i) f

Singularity.completeFamily_key.type:
∀ {K : Type u_1} [inst : Field K] {Γ₀ : Type uV} [inst_1 : LinearOrderedCommGroupWithZero Γ₀]
  {ν w : Valuation (Polynomial K) Γ₀} {φ : Polynomial K} {hle : ∀ (f : Polynomial K), ν f ≤ w f} {hm : φ.Monic}
  {hlt : ν φ < w φ} {hlow : ∀ (f : Polynomial K), f.degree < φ.degree → ν f = w f}
  (i : (↑(Singularity.completeValues ν φ))ᵒᵈ),
  (Singularity.completeFamily hle hm hlt hlow).key i = Singularity.completeKey i

Singularity.completeFamily_value.type:
∀ {K : Type u_1} [inst : Field K] {Γ₀ : Type uV} [inst_1 : LinearOrderedCommGroupWithZero Γ₀]
  {ν w : Valuation (Polynomial K) Γ₀} {φ : Polynomial K} {hle : ∀ (f : Polynomial K), ν f ≤ w f} {hm : φ.Monic}
  {hlt : ν φ < w φ} {hlow : ∀ (f : Polynomial K), f.degree < φ.degree → ν f = w f}
  (i : (↑(Singularity.completeValues ν φ))ᵒᵈ),
  (Singularity.completeFamily hle hm hlt hlow).value i = ↑(OrderDual.ofDual i)

Singularity.derivation_eq_zero_of_aeval_.type:
∀ {k : Type u_1} {A : Type u_2} {M : Type u_3} [inst : CommRing k] [inst_1 : CommRing A] [inst_2 : Algebra k A]
  [inst_3 : AddCommGroup M] [inst_4 : Module A M] [inst_5 : Module k M] (D : Derivation k A M) {b : A}
  {Q : Polynomial k}, (Polynomial.aeval b) Q = 0 → IsUnit ((Polynomial.aeval b) (Polynomial.derivative Q)) → D b = 0

Singularity.eq_zero_of_sum_weightSpace.type:
∀ {k : Type u_1} {R : Type u_2} [inst : CommRing k] [inst_1 : CommRing R] [inst_2 : Algebra k R] {p : ℕ}
  [inst_3 : Fact (Nat.Prime p)] [CharP R p] (δ : Derivation k R R) {c : ZMod p → R},
  (∀ (i : ZMod p), c i ∈ Singularity.weightSpace δ i) → ∑ i, c i = 0 → ∀ (i : ZMod p), c i = 0

Singularity.exists_centerChart_eq_X_pow_.type:
∀ {σ : Type u_1} {k : Type u_2} [inst : Field k] [inst_1 : DecidableEq σ] {S : Finset σ} {j : σ} (t : σ → k) {s : ℕ}
  {f : MvPolynomial σ k},
  f ∈ Ideal.span (MvPolynomial.X '' ↑S) ^ s → ∃ f', (Singularity.centerChart S j t) f = MvPolynomial.X j ^ s * f'

Singularity.exists_chartSubst_eq_X_pow_m.type:
∀ {σ : Type u_1} {R : Type u_2} [inst : CommRing R] [inst_1 : DecidableEq σ] {S : Finset σ} {c : σ} {m : ℕ}
  {f : MvPolynomial σ R},
  f ∈ Singularity.chartCenterIdeal S ^ m → ∃ g, (Singularity.chartSubst S c) f = MvPolynomial.X c ^ m * g

Singularity.exists_eq_macLaneChain.type:
∀ {K : Type u_1} [inst : Field K] {Γ₀ : Type u_2} [inst_1 : LinearOrderedCommGroupWithZero Γ₀] {v : Valuation K Γ₀}
  {ν : Valuation (Polynomial K) Γ₀},
  (∀ (a : K), ν (Polynomial.C a) = v a) → ∀ (n : ℕ) (f : Polynomial K), ∃ g, (Singularity.macLaneChain v ν n) f = ν g

Singularity.exists_eq_monomialValuationF.type:
∀ {K : Type u_1} [inst : Field K] {Γ₀ : Type u_2} [inst_1 : LinearOrderedCommGroupWithZero Γ₀] {v : Valuation K Γ₀}
  {γ : Γ₀} {f : Polynomial K},
  Singularity.monomialValuationFun v γ f ≠ 0 → ∃ i, v (f.coeff i) * γ ^ i = Singularity.monomialValuationFun v γ f

Singularity.exists_isIntegral_mul_eq_one.type:
∀ {K : Type u_1} {L : Type u_2} [inst : Field K] [inst_1 : Field L] [inst_2 : Algebra K L] {A : ValuationSubring K}
  [inst_3 : Algebra (↥A) L] [IsScalarTower (↥A) K L] [FiniteDimensional K L] {W : ValuationSubring L},
  W.comap (algebraMap K L) = A → ∀ {x : L}, x ∈ W → ∃ u, IsIntegral (↥A) u ∧ IsIntegral (↥A) (u * x) ∧ W.valuation u = 1

Singularity.exists_isRegularSystemOfPara.type:
∀ {R : Type u} [inst : CommRing R] [inst_1 : IsRegularLocalRing R] (P : Ideal R) [IsRegularLocalRing (R ⧸ P)],
  ringKrullDim (R ⧸ P) + 1 = ringKrullDim R →
    ∃ s, Singularity.IsRegularSystemOfParameters s ∧ ∃ x ∈ s, P = Ideal.span {x}

Singularity.exists_map_chartSeqMap_eq_sp.type:
∀ {σ : Type u_1} {R : Type u_2} [inst : CommRing R] [inst_1 : DecidableEq σ] [IsDomain R] {l : List (Finset σ × σ)}
  {I : Ideal (MvPolynomial σ R)},
  Singularity.IsChartSeqOfOrder 1 l I →
    Singularity.chartSeqTransform 1 l I = ⊤ →
      ∃ e, Ideal.map (Singularity.chartSeqMap l) I = Ideal.span {(MvPolynomial.monomial e) 1}

Singularity.exists_pow_valuation_eq_alge.type:
