  [inst_3 : LinearOrderedCommGroupWithZero Γ₀] {w : Valuation L Γ₀} {z : L},
  z ≠ 0 → IsAlgebraic K z → ∃ n, 0 < n ∧ ∃ c, w (z ^ n) = w ((algebraMap K L) c)

Singularity.finite_range_valuation_quoti.type:
∀ {K : Type u_1} {L : Type u_2} [inst : Field K] [inst_1 : Field L] [inst_2 : Algebra K L] {Γ₁ : Type u_4}
  [inst_3 : LinearOrderedCommGroupWithZero Γ₁] (vL : Valuation L Γ₁) {F : IntermediateField K L}
  [FiniteDimensional (↥F) L] (H : Subgroup Γ₁ˣ),
  (∀ (u : Lˣ), ↑u ∈ F → (Units.map ↑vL) u ∈ H) → (Set.range fun u => ↑((Units.map ↑vL) u)).Finite

Singularity.finrank_eq_one_comp_of_finra.type:
∀ {K : Type u_1} {L : Type u_2} [inst : Field K] [inst_1 : Field L] [inst_2 : Algebra K L] {M : Type u_3}
  [inst_3 : Field M] [inst_4 : Algebra L M] [inst_5 : Algebra K M] [IsScalarTower K L M],
  Module.finrank K L = 1 → Module.finrank L M = 1 → Module.finrank K M = 1 ∧ Algebra.IsSeparable K M

Singularity.fourPoints_chart.type:
∀ (k : Type u_1) [inst : CommRing k] [Nontrivial k],
  have lam := MvPolynomial.X 0;
  have t := MvPolynomial.X 1;
  lam * t - lam = lam * (t - 1) ∧ 0 ≠ 1

Singularity.gradingProj.congr_simp.type:
∀ {k : Type u_1} {R : Type u_2} [inst : CommRing k] [inst_1 : CommRing R] [inst_2 : Algebra k R] {p : ℕ}
  [inst_3 : CharP R p] (δ δ_1 : Derivation k R R),
  δ = δ_1 → ∀ (i i_1 : ZMod p), i = i_1 → Singularity.gradingProj δ i = Singularity.gradingProj δ_1 i_1

