∀ {k : Type u_1} {R : Type u_2} [inst : CommRing k] [inst_1 : CommRing R] [inst_2 : Algebra k R] {p : ℕ}
  [Fact (Nat.Prime p)] [inst_4 : CharP R p] (δ : Derivation k R R) {j : ZMod p} {g : R},
  g ∈ Singularity.weightSpace δ j → ∀ (i : ZMod p), (Singularity.gradingProj δ i) g = if j = i then g else 0

Singularity.gradingProj_mem.type:
∀ {k : Type u_1} {R : Type u_2} [inst : CommRing k] [inst_1 : CommRing R] [inst_2 : Algebra k R] {p : ℕ}
  [Fact (Nat.Prime p)] [inst_4 : CharP R p] (δ : Derivation k R R),
