Singularity.le_macLaneChain.type:
∀ {K : Type u_1} [inst : Field K] {Γ₀ : Type u_2} [inst_1 : LinearOrderedCommGroupWithZero Γ₀] {v : Valuation K Γ₀}
  {ν : Valuation (Polynomial K) Γ₀},
  (∀ (a : K), ν (Polynomial.C a) = v a) → ∀ (n : ℕ) (f : Polynomial K), ν f ≤ (Singularity.macLaneChain v ν n) f

Singularity.linearIndependent_of_valuati.type:
∀ {K : Type u_1} {L : Type u_2} [inst : Field K] [inst_1 : Field L] [inst_2 : Algebra K L] {Γ₁ : Type u_4}
  [inst_3 : LinearOrderedCommGroupWithZero Γ₁] (vL : Valuation L Γ₁) {F : IntermediateField K L} {m : Type u_5}
  [Fintype m] {z : m → L},
  (∀ (i : m), z i ≠ 0) →
    (∀ (i j : m) (c d : ↥F), c ≠ 0 → d ≠ 0 → vL (↑c * z i) = vL (↑d * z j) → i = j) → LinearIndependent (↥F) z

Singularity.logJacobianCenter_le_centerD.type:
∀ {σ : Type u_1} {k : Type u_2} [inst : Field k] [inst_1 : DecidableEq σ] {Δ S : Finset σ} {n : ℕ}
  {g : MvPolynomial σ k},
