Singularity.macLaneBelow_macLaneChain.type:
∀ {K : Type u_1} [inst : Field K] {Γ₀ : Type u_2} [inst_1 : LinearOrderedCommGroupWithZero Γ₀] {v : Valuation K Γ₀}
  {ν : Valuation (Polynomial K) Γ₀},
  (∀ (a : K), ν (Polynomial.C a) = v a) → ∀ (n : ℕ), Singularity.MacLaneBelow ν (Singularity.macLaneChain v ν n)

Singularity.macLaneChain_eq_of_le.type:
∀ {K : Type u_1} [inst : Field K] {Γ₀ : Type u_2} [inst_1 : LinearOrderedCommGroupWithZero Γ₀] {v : Valuation K Γ₀}
  {ν : Valuation (Polynomial K) Γ₀} {n m : ℕ},
  n ≤ m → Singularity.macLaneChain v ν n = ν → Singularity.macLaneChain v ν m = ν

Singularity.macLaneChain_succ.type:
∀ {K : Type u_1} [inst : Field K] {Γ₀ : Type u_2} [inst_1 : LinearOrderedCommGroupWithZero Γ₀] {v : Valuation K Γ₀}
  {ν : Valuation (Polynomial K) Γ₀} (n : ℕ),
  Singularity.macLaneChain v ν (n + 1) = Singularity.macLaneStep ν (Singularity.macLaneChain v ν n)

Singularity.macLaneChain_succ_eq.type:
∀ {K : Type u_1} [inst : Field K] {Γ₀ : Type u_2} [inst_1 : LinearOrderedCommGroupWithZero Γ₀] {v : Valuation K Γ₀}
  {ν : Valuation (Polynomial K) Γ₀} (hν : ∀ (a : K), ν (Polynomial.C a) = v a) {n : ℕ}
  (hne : Singularity.macLaneChain v ν n ≠ ν),
  Singularity.macLaneChain v ν (n + 1) =
    Singularity.augmentedValuation (Singularity.macLaneChain v ν n) (Singularity.macLaneChainKey v ν n)
      (ν (Singularity.macLaneChainKey v ν n)) ⋯ ⋯

Singularity.macLaneChain_succ_le.type:
∀ {K : Type u_1} [inst : Field K] {Γ₀ : Type u_2} [inst_1 : LinearOrderedCommGroupWithZero Γ₀] {v : Valuation K Γ₀}
  {ν : Valuation (Polynomial K) Γ₀} (n : ℕ) (f : Polynomial K),
  (Singularity.macLaneChain v ν (n + 1)) f ≤ (Singularity.macLaneChain v ν n) f

Singularity.map_chartSeqMap_le.type:
∀ {σ : Type u_1} {R : Type u_2} [inst : CommRing R] [inst_1 : DecidableEq σ] [IsDomain R] {m : ℕ}
  {l : List (Finset σ × σ)} {I : Ideal (MvPolynomial σ R)},
