Singularity.map_comp_le_span.type:
∀ {P : Type u_3} {Q : Type u_4} {Q' : Type u_5} [inst : CommRing P] [inst_1 : CommRing Q] [inst_2 : CommRing Q']
  (φ : P →+* Q) (ψ : Q →+* Q') {x : Q} {m : ℕ} {I : Ideal P},
  Ideal.map φ I ≤ Ideal.span {x ^ m} → Ideal.map (ψ.comp φ) I ≤ Ideal.span {ψ x ^ m}

Singularity.map_mem_centerSubring.type:
∀ {K : Type u_1} {L : Type u_2} [inst : Field K] [inst_1 : Field L] {W : ValuationSubring L} {f : K →+* L}
  {R : Subring K} {B : Subring L},
  (∀ a ∈ R, f a ∈ B) → ∀ {x : K}, x ∈ Singularity.centerSubring (W.comap f) R → f x ∈ Singularity.centerSubring W B

Singularity.map_pointChart_le_span.type:
∀ {σ : Type u_1} {k : Type u_2} [inst : Field k] [inst_1 : DecidableEq σ] (j : σ) (t : σ → k) {m : ℕ}
  {I : Ideal (MvPolynomial σ k)},
  ↑m ≤ Singularity.idealOrd I → Ideal.map (Singularity.pointChart j t) I ≤ Ideal.span {MvPolynomial.X j ^ m}

Singularity.map_pointChart_span_le.type:
∀ {σ : Type u_1} {k : Type u_2} [inst : Field k] [inst_1 : DecidableEq σ] [inst_2 : DecidableEq k] {j : σ} {t : σ → k}
  {S : Set (MvPolynomial σ k)} {r : σ →₀ ℕ} {c : ℕ},
  (∀ s ∈ S, (MvPolynomial.monomial r) 1 ∣ s ∧ ↑(Finsupp.degree r + c) ≤ Singularity.ord s) →
    Ideal.map (Singularity.pointChart j t) (Ideal.span S) ≤
      Ideal.span
        {MvPolynomial.X j ^ (Finsupp.degree r + c) * (MvPolynomial.monomial (Singularity.chartExponent j t r)) 1}

Singularity.map_span_monomial_le_of_adap.type:
∀ {σ : Type u_1} {k : Type u_2} [inst : Field k] [DecidableEq σ] {Δ : Finset σ}
  {φ : MvPolynomial σ k →ₐ[k] MvPolynomial σ k},
  (∀ l ∈ Δ, ∃ c, φ (MvPolynomial.X l) = MvPolynomial.C c * MvPolynomial.X l) →
    ∀ {s : σ →₀ ℕ},
      (∀ i ∉ Δ, s i = 0) →
        Ideal.map φ (Ideal.span {(MvPolynomial.monomial s) 1}) ≤ Ideal.span {(MvPolynomial.monomial s) 1}

Singularity.mem_chartTransformIdeal.type:
∀ {σ : Type u_1} {k : Type u_2} [inst : Field k] [inst_1 : DecidableEq σ] {j : σ} {t : σ → k} {m : ℕ}
  {I : Ideal (MvPolynomial σ k)} {g : MvPolynomial σ k},
  g ∈ Singularity.chartTransformIdeal j t m I ↔ MvPolynomial.X j ^ m * g ∈ Ideal.map (Singularity.pointChart j t) I

Singularity.mem_commonWeightSpace.type:
∀ {k : Type u_1} {R : Type u_2} {ι : Type u_3} [inst : CommRing k] [inst_1 : CommRing R] [inst_2 : Algebra k R] {p : ℕ}
  {δ : ι → Derivation k R R} {χ : ι → ZMod p} {g : R},
  g ∈ Singularity.commonWeightSpace δ χ ↔ ∀ (l : ι), (δ l) g = (χ l).cast * g

Singularity.mem_maximalIdeal_iff_of_coma.type:
∀ {K : Type u_1} {L : Type u_2} [inst : Field K] [inst_1 : Field L] [inst_2 : Algebra K L] {A : ValuationSubring K}
  [inst_3 : Algebra (↥A) L] [IsScalarTower (↥A) K L] {W : ValuationSubring L},
  W.comap (algebraMap K L) = A → ∀ (a : ↥A), a ∈ IsLocalRing.maximalIdeal ↥A ↔ W.valuation ((algebraMap K L) ↑a) < 1

Singularity.mem_of_isIntegral.type:
∀ {K : Type u_1} {L : Type u_2} [inst : Field K] [inst_1 : Field L] [inst_2 : Algebra K L] {A : ValuationSubring K}
  [inst_3 : Algebra (↥A) L] [IsScalarTower (↥A) K L] {W : ValuationSubring L},
  W.comap (algebraMap K L) = A → ∀ {x : L}, IsIntegral (↥A) x → x ∈ W

Singularity.mem_tangentDerivations_X_iff.type:
∀ {σ : Type u_1} {k : Type u_2} [inst : CommRing k] {Δ : Set σ}
  {δ : Derivation k (MvPolynomial σ k) (MvPolynomial σ k)},
  δ ∈ Singularity.tangentDerivations k (MvPolynomial.X '' Δ) ↔
    ∀ i ∈ Δ, δ (MvPolynomial.X i) ∈ Ideal.span {MvPolynomial.X i}

Singularity.mem_valueGroup_comap_algebra.type:
∀ {K : Type u_1} {L : Type u_2} [inst : Field K] [inst_1 : Field L] [inst_2 : Algebra K L] {Γ₁ : Type u_4}
  [inst_3 : LinearOrderedCommGroupWithZero Γ₁] (vL : Valuation L Γ₁) (y : Γ₁ˣ),
  y ∈ (↑(Valuation.comap (algebraMap K L) vL)).valueGroup ↔ ∃ c, vL ((algebraMap K L) c) = ↑y

Singularity.mem_valueGroup_comap_interme.type:
∀ {K : Type u_1} {L : Type u_2} [inst : Field K] [inst_1 : Field L] [inst_2 : Algebra K L] {Γ₁ : Type u_4}
  [inst_3 : LinearOrderedCommGroupWithZero Γ₁] (vL : Valuation L Γ₁) (F : IntermediateField K L) (y : Γ₁ˣ),
  y ∈ (↑(Valuation.comap (algebraMap (↥F) L) vL)).valueGroup ↔ ∃ z ∈ F, vL z = ↑y

Singularity.monomialValuationFun_le_iff.type:
∀ {K : Type u_1} [inst : Field K] {Γ₀ : Type u_2} [inst_1 : LinearOrderedCommGroupWithZero Γ₀] {v : Valuation K Γ₀}
  {γ : Γ₀} {f : Polynomial K} {c : Γ₀},
  Singularity.monomialValuationFun v γ f ≤ c ↔ ∀ (i : ℕ), v (f.coeff i) * γ ^ i ≤ c

Singularity.mul_mem_weightSpace.type:
∀ {k : Type u_1} {R : Type u_2} [inst : CommRing k] [inst_1 : CommRing R] [inst_2 : Algebra k R] {p : ℕ}
  [inst_3 : Fact (Nat.Prime p)] [CharP R p] (δ : Derivation k R R) {i j : ZMod p} {g h : R},
  g ∈ Singularity.weightSpace δ i → h ∈ Singularity.weightSpace δ j → g * h ∈ Singularity.weightSpace δ (i + j)

Singularity.mul_prod_eq_pow_mul_prod_cha.type:
∀ {ι : Type u_1} {R : Type u_2} [inst : DecidableEq ι] [inst_1 : Fintype ι] [inst_2 : CommMonoid R] {x : ι → R} {i : ι}
  {a : ι → ℕ} {p : ℕ} {u v w : R},
  u = v ^ a i * w ^ p → u * ∏ j, x j ^ a j = w ^ p * ∏ j, Singularity.changeParam x i v j ^ a j

Singularity.pointChart_eq_X_pow_mul_char.type:
∀ {σ : Type u_1} {k : Type u_2} [inst : Field k] [inst_1 : DecidableEq σ] (j : σ) (t : σ → k) {m : ℕ}
  {f : MvPolynomial σ k},
  ↑m ≤ Singularity.ord f → (Singularity.pointChart j t) f = MvPolynomial.X j ^ m * Singularity.chartTransform j t m f

Singularity.pointChart_of_isHomogeneous.type:
∀ {σ : Type u_1} {k : Type u_2} [inst : Field k] [inst_1 : DecidableEq σ] (j : σ) (t : σ → k) {m : ℕ}
  {p : MvPolynomial σ k},
  p.IsHomogeneous m → (Singularity.pointChart j t) p = MvPolynomial.X j ^ m * (Singularity.chartRest j t) p

Singularity.pow_mem_range_of_finrank_eq.type:
∀ {E : Type u_1} {E' : Type u_2} [inst : Field E] [inst_1 : Field E'] [inst_2 : Algebra E E'] {p : ℕ}
  [hp : Fact (Nat.Prime p)] [CharP E p] [IsPurelyInseparable E E'],
  Module.finrank E E' = p → ∀ (θ : E'), θ ^ p ∈ Set.range ⇑(algebraMap E E')

Singularity.primesOver_eq_maximalIdeal_o.type:
∀ {R : Type u_1} {S : Type u_2} [inst : CommRing R] [inst_1 : CommRing S] [inst_2 : Algebra R S]
  [inst_3 : IsLocalRing S] [Algebra.IsIntegral R S] [FaithfulSMul R S] (p : Ideal R) [p.IsMaximal],
  p.primesOver S = {IsLocalRing.maximalIdeal S}

Singularity.quarticNormHom.type:
(k : Type u_1) →
  [inst : CommRing k] →
    MvPolynomial (Fin 3) k →ₐ[k] MvPolynomial (Fin 3) k ⧸ Ideal.span {MvPolynomial.X 2 ^ 2 - (1 + MvPolynomial.X 1 ^ 4)}

Singularity.range_rootHom_le.type:
∀ {E : Type u_1} {E' : Type u_2} [inst : Field E] [inst_1 : Field E'] [inst_2 : Algebra E E'] {R : Subring E} {p : ℕ}
  {y : ↥R} {z : E'} {hy : (algebraMap E E') ↑y = z ^ p} {S : Subring E'},
  (∀ (r : ↥R), (algebraMap E E') ↑r ∈ S) → z ∈ S → (Singularity.rootHom R hy).range ≤ S

Singularity.residue_mem_adjoin_of_mem_ad.type:
∀ {k : Type u_1} {K : Type u_2} [inst : Field k] [inst_1 : Field K] [inst_2 : Algebra k K] {V : ValuationSubring K}
  [inst_3 : Algebra k ↥V] [inst_4 : IsScalarTower k (↥V) K] {κ : Type u_3} {y : κ → ↥V}
  (hy : AlgebraicIndependent k fun j => (IsLocalRing.residue ↥V) (y j)) {c : K}
  (hc : c ∈ IntermediateField.adjoin k (Set.range fun j => ↑(y j))),
  (IsLocalRing.residue ↥V) ⟨c, ⋯⟩ ∈ IntermediateField.adjoin k (Set.range fun j => (IsLocalRing.residue ↥V) (y j))

Singularity.rootHom_injective.type:
∀ {E : Type u_1} {E' : Type u_2} [inst : Field E] [inst_1 : Field E'] [inst_2 : Algebra E E'] (R : Subring E) {p : ℕ}
  {y : ↥R} {z : E'} (hy : (algebraMap E E') ↑y = z ^ p),
  p ≠ 0 → Irreducible (Polynomial.X ^ p - Polynomial.C ↑y) → Function.Injective ⇑(Singularity.rootHom R hy)

Singularity.rootHom_of.type:
∀ {E : Type u_1} {E' : Type u_2} [inst : Field E] [inst_1 : Field E'] [inst_2 : Algebra E E'] (R : Subring E) {p : ℕ}
  {y : ↥R} {z : E'} (hy : (algebraMap E E') ↑y = z ^ p) (r : ↥R),
  (Singularity.rootHom R hy) ((AdjoinRoot.of (Polynomial.X ^ p - Polynomial.C y)) r) = (algebraMap E E') ↑r

Singularity.rootHom_root.type:
∀ {E : Type u_1} {E' : Type u_2} [inst : Field E] [inst_1 : Field E'] [inst_2 : Algebra E E'] (R : Subring E) {p : ℕ}
  {y : ↥R} {z : E'} (hy : (algebraMap E E') ↑y = z ^ p),
  (Singularity.rootHom R hy) (AdjoinRoot.root (Polynomial.X ^ p - Polynomial.C y)) = z

Singularity.sub_castHom_apply_of_mem.type:
∀ {k : Type u_1} {R : Type u_2} [inst : CommRing k] [inst_1 : CommRing R] [inst_2 : Algebra k R] {p : ℕ}
  [inst_3 : Fact (Nat.Prime p)] [inst_4 : CharP R p] (δ : Derivation k R R) {j : ZMod p} {g : R},
  g ∈ Singularity.weightSpace δ j → ∀ (i : ZMod p), (↑δ - (ZMod.castHom ⋯ (Module.End k R)) i) g = (j - i).cast * g

Singularity.sub_castHom_mul_gradingProj.type:
∀ {k : Type u_1} {R : Type u_2} [inst : CommRing k] [inst_1 : CommRing R] [inst_2 : Algebra k R] {p : ℕ}
  [Fact (Nat.Prime p)] [inst_4 : CharP R p] (δ : Derivation k R R),
  ↑δ ^ p = ↑δ → ∀ (i : ZMod p), (↑δ - (ZMod.castHom ⋯ (Module.End k R)) i) * Singularity.gradingProj δ i = 0

Singularity.sum_gradingProj_apply.type:
∀ {k : Type u_1} {R : Type u_2} [inst : CommRing k] [inst_1 : CommRing R] [inst_2 : Algebra k R] {p : ℕ}
  [inst_3 : Fact (Nat.Prime p)] [inst_4 : CharP R p] (δ : Derivation k R R) (g : R),
  ∑ i, (Singularity.gradingProj δ i) g = g

Singularity.valuation_eq_one_of_sq_eq.type:
∀ {k : Type u_1} {L : Type u_2} [inst : Field k] [inst_1 : Field L] [inst_2 : Algebra k L] {Γ : Type u_3}
  [inst_3 : LinearOrderedCommGroupWithZero Γ] (w : Valuation L Γ),
  (∀ (c : k), c ≠ 0 → w ((algebraMap k L) c) = 1) → ∀ {c : k}, c ≠ 0 → ∀ {s : L}, s ^ 2 = (algebraMap k L) c → w s = 1

Singularity.valuation_map_le_map_of_stab.type:
∀ {K : Type u_1} {E : Type u_3} [inst : Field K] [inst_1 : Field E] [inst_2 : Algebra K E] {Γ : Type u_4}
  [inst_3 : LinearOrderedCommGroupWithZero Γ] (w : Valuation E Γ) (φ : E →ₐ[K] E),
  (∀ (x : E), w x ≤ 1 → w (φ x) ≤ 1) → ∀ {a b : E}, w a ≤ w b → w (φ a) ≤ w (φ b)

Singularity.valuation_ne_one_of_mem_maxi.type:
∀ {K : Type u_1} [inst : Field K] {V : ValuationSubring K} {R : Subring K}
  [inst_1 : IsLocalRing ↥(Singularity.centerSubring V R)] {r : ↥(Singularity.centerSubring V R)},
  r ∈ IsLocalRing.maximalIdeal ↥(Singularity.centerSubring V R) → V.valuation ↑r ≠ 1
